cat > /tmp/fetch_senders.py << 'PYEOF'
import json, subprocess, sys, concurrent.futures, re

with open('/tmp/promo_ids.json') as f:
    ids = json.load(f)

print(f"Processing {len(ids)} message IDs...", file=sys.stderr)

def fetch_one(msg_id):
    try:
        params = json.dumps({
            "userId": "me",
            "id": msg_id,
            "format": "metadata",
            "metadataHeaders": ["From"]
        })
        result = subprocess.run(
            ["gws", "gmail", "users", "messages", "get", "--params", params],
            capture_output=True, text=True, timeout=30
        )
        out = result.stdout
        # Parse JSON from output (skip any log lines)
        lines = out.strip().split('\n')
        json_start = 0
        for i, line in enumerate(lines):
            if line.strip().startswith('{'):
                json_start = i
                break
        json_text = '\n'.join(lines[json_start:])
        data = json.loads(json_text)
        headers = data.get("payload", {}).get("headers", [])
        for h in headers:
            if h.get("name") == "From":
                return (msg_id, h.get("value", ""))
        return (msg_id, "")
    except Exception as e:
        return (msg_id, f"ERROR: {e}")

results = []
with concurrent.futures.ThreadPoolExecutor(max_workers=20) as executor:
    futures = {executor.submit(fetch_one, mid): mid for mid in ids}
    for i, future in enumerate(concurrent.futures.as_completed(futures)):
        msg_id, from_val = future.result()
        results.append((msg_id, from_val))
        if (i+1) % 50 == 0:
            print(f"  Processed {i+1}/{len(ids)}...", file=sys.stderr)

print(f"Done. Got {len(results)} results.", file=sys.stderr)

# Save raw results
with open('/tmp/promo_from_raw.txt', 'w') as f:
    for msg_id, from_val in results:
        f.write(f"{msg_id}\t{from_val}\n")

# Parse email addresses and names
def parse_from(from_str):
    """Parse 'Name <email@domain>' or 'email@domain' format"""
    m = re.match(r'^(.*?)\s*<(.+?)>\s*$', from_str)
    if m:
        return m.group(1).strip(), m.group(2).strip()
    # Try just email
    m = re.match(r'^\s*([^\s]+@[^\s]+)\s*$', from_str)
    if m:
        return "", m.group(1).strip()
    return "", from_str.strip()

# Deduplicate by email
senders = {}
for msg_id, from_val in results:
    if not from_val or from_val.startswith("ERROR"):
        continue
    name, email = parse_from(from_val)
    if email and email not in senders:
        senders[email] = {"name": name, "from_val": from_val, "msg_id": msg_id}

# Write deduplicated senders
with open('/tmp/promo_senders.txt', 'w') as f:
    for email, info in sorted(senders.items()):
        if info["name"]:
            f.write(f'{info["name"]} <{email}>\n')
        else:
            f.write(f'{email}\n')

print(f"\nUnique senders: {len(senders)}")
print("Saved to /tmp/promo_senders.txt")

# Save sender->msg_id mapping for unsubscribe lookup
with open('/tmp/promo_sender_msgids.json', 'w') as f:
    json.dump({email: info["msg_id"] for email, info in senders.items()}, f)

# Print all unique senders
for email, info in sorted(senders.items()):
    if info["name"]:
        print(f'  {info["name"]} <{email}>')
    else:
        print(f'  {email}')
